
;

    // 首屏主题预置：必须在 CSS 渲染前设置 data-theme，否则启动会闪白/主题跳变。
    // 主题是 UI 偏好，单独明文存 localStorage（登录页阶段即可读，无需解锁 vault）；
    // vault 内仍保存完整设置，解锁后以 vault 为准。
    (function () {
      try {
        var prefs = JSON.parse(localStorage.getItem('wb-ui-prefs') || '{}');
        var t = prefs.theme || 'auto';
        if (t === 'auto') {
          t = (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) ? 'dark' : 'light';
        }
        document.documentElement.setAttribute('data-theme', t === 'dark' ? 'dark' : 'light');
        // 皮肤预置（皮肤首屏防闪，与 data-theme 同构）：skin 同样存 wb-ui-prefs，
        // 不在此预置的话，data-skin 要等 boot 的 applySkin（晚于 CSS 首绘）才生效——
        // 非 p0 用户会先按 P0 渲染再跳变。只在 CSS 渲染前显式设置，其余情况保持静态默认 p0。
        document.documentElement.setAttribute('data-skin', (prefs.skin === 'p1' || prefs.skin === 'moyin') ? prefs.skin : 'p0');
      } catch (e) {
        document.documentElement.setAttribute('data-theme', 'dark');
      }
    })();
  

;

