      // 场景: 保存写盘往返毫秒窗口内用户点"锁定" → lock() 置 _meta=null/_dataKey=null
      // → 原代码 await put(STORE_VAULT) 后读 _meta 拿到 null → put(STORE_META, null)
      // → 下次启动 vault 判不存在 → first_run 覆盖, 旧数据只剩槽位冷备
