  // ============================================================
  // P4.3.2: 受限环境保存兜底 Modal (从 dist/index.html UI 块 L5794-5837 搬入)
  // 走 §五 组件化清单 "Modal 范畴"
  // - 跨 IIFE 调用: window.showToast (本文件 IIFE)
  // - 跨 IIFE 调用: window.escapeHtml (dom.js)
  // - 跨 IIFE 调用: navigator.clipboard.writeText (浏览器 API)
  // ============================================================

  /**
   * 受限环境下的保存兜底：把待保存内容展示出来供手动复制。
   *
   * 用于跨源 iframe（如资料库）——此时 FS API 被规范禁止、下载被 sandbox 拦截、
   * 剪贴板也被 Permissions Policy 禁用，只能退到「全选 + 手动 Ctrl+C」。
   * 关键是**让用户明确知道文件没保存**，而不是给一个成功的假象。
   */
  function showSaveFallbackModal(filename, text) {
    const old = document.getElementById('save-fallback-overlay');
    if (old) old.remove();

    const wrap = document.createElement('div');
    wrap.id = 'save-fallback-overlay';
    wrap.setAttribute('role', 'dialog');
    wrap.setAttribute('aria-modal', 'true');
    wrap.setAttribute('aria-label', '手动保存文件');
    wrap.style.cssText = 'position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;background:var(--overlay);padding:20px;box-sizing:border-box';
    wrap.innerHTML =
      '<div style="width:min(680px,100%);max-height:88vh;overflow:auto;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius-lg);padding:20px;font-family:var(--font-body)">' +
        '<div style="font-size:15px;font-weight:500;color:var(--fg);margin-bottom:8px">当前环境无法保存文件</div>' +
        '<div style="font-size:13px;color:var(--muted);line-height:1.6;margin-bottom:14px">' +
          '页面运行在嵌入环境中，浏览器安全策略禁止写入磁盘，<b style="color:var(--fg);font-weight:500">文件尚未保存到你的电脑</b>。<br>' +
          '请复制下面内容自行保存为 <span style="color:var(--fg);font-family:var(--font-mono)">' + window.escapeHtml(filename) + '</span>，' +
          '或在设置页点击「在独立窗口打开」后重试。' +
        '</div>' +
        '<textarea id="save-fallback-text" readonly style="width:100%;height:240px;box-sizing:border-box;background:var(--surface-2);color:var(--fg);border:1px solid var(--border);border-radius:var(--radius-md);padding:10px;font-family:var(--font-mono);font-size:12px;line-height:1.5;resize:vertical"></textarea>' +
        '<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px">' +
          '<button type="button" id="save-fallback-close" class="btn btn-secondary"><span>关闭</span></button>' +
          '<button type="button" id="save-fallback-copy" class="btn btn-primary"><span>全选并复制</span></button>' +
        '</div>' +
      '</div>';
    document.body.appendChild(wrap);

    const ta = wrap.querySelector('#save-fallback-text');
    ta.value = text;   // 用 value 赋值，避免内容里的尖括号破坏结构

    const close = () => wrap.remove();
    wrap.querySelector('#save-fallback-close').addEventListener('click', () => close());
    wrap.addEventListener('click', e => { if (e.target === wrap) close(); });
    wrap.querySelector('#save-fallback-copy').addEventListener('click', () => {
      ta.focus();
      ta.select();
      // 剪贴板在跨源 iframe 同样被禁；失败时退回手动复制提示
      navigator.clipboard.writeText(text).then(
        () => window.showToast('已复制到剪贴板', 'success'),
        () => window.showToast('已全选，请按 Ctrl+C 复制', 'info')
      );
    });
    ta.focus();
    ta.select();
  }

  // === P4.3.2 暴露 ===
  window.showSaveFallbackModal = showSaveFallbackModal;

  // ============================================================
  // 主题/DOM 工具 (P4.1a.1 阶段从 UI 块抽入)
  // ============================================================

  /**
   * 同步显示名称到：侧边栏用户名 + 头像 + 问候语
   * P4.1a.1: 从 dist/index.html L5598-5606 字节级搬入
   * 依赖 UI 块顶层 (全局): getDisplayName / avatarInitials / updateGreeting
   * P3.5 settings.js: getDisplayName 搬到 settings.js IIFE, 跨 IIFE 改 window.getDisplayName
   */
  function applyDisplayName() {
    const name = window.getDisplayName();
    const nameEl = document.getElementById('user-name');
    const avatarEl = document.getElementById('user-avatar');
    if (nameEl) nameEl.textContent = name || 'Custos';
    if (avatarEl) avatarEl.textContent = avatarInitials(name);
    // P3.5: updateGreeting 已搬到 src/ui/dashboard.js, 跨 IIFE 调走 window.
    window.updateGreeting();
  }

  // 同步工作台名称到：登录页标题 / 侧边栏品牌 / 浏览器 title
  // P4.1a.1: 从 dist/index.html L5620-5628 字节级搬入
  // 依赖 UI 块顶层 (全局): getWorkbenchName
  // P3.5 settings.js: getWorkbenchName 搬到 settings.js IIFE, 跨 IIFE 改 window.getWorkbenchName
  function applyWorkbenchName() {
    const name = window.getWorkbenchName();
    const unlockEl = document.getElementById('unlock-title');
    if (unlockEl) unlockEl.textContent = name;
    const sidebarEl = document.getElementById('sidebar-brand');
    if (sidebarEl) sidebarEl.textContent = name;
    document.title = name;   // 窗口标题即工作台名（不再带「苹果风格工作台 ·」前缀）
  }

  // P4.1a.1: 从 dist/index.html L5630-5644 字节级搬入
  // 依赖 UI 块顶层 (全局): APP_SETTINGS (const) + window.persistSettings (storage.js 暴露)
  function applyTheme(theme) {
    // 无谓写守卫：值未变时不回写 —— 解锁/启动路径会重放已保存值、用户也会重复点击
    // 当前主题，此前每次都会 persistSettings → 多一次整库落盘（云端档即一次空写）。
    const themeChanged = APP_SETTINGS.theme !== theme;
    APP_SETTINGS.theme = theme;
    const html = document.documentElement;
    let actualTheme;  // 记录实际生效的主题(auto 时是 light 或 dark,非 'auto')
    if (theme === 'dark') {
      html.setAttribute('data-theme', 'dark');
      actualTheme = 'dark';
    } else if (theme === 'light') {
      html.setAttribute('data-theme', 'light');
      actualTheme = 'light';
    } else {
      // auto - 跟随系统
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      actualTheme = prefersDark ? 'dark' : 'light';
      html.setAttribute('data-theme', actualTheme);
    }
    // 同步右上角 #theme-toggle 图标(2 态 moon/sun,表示当前实际显示主题)
    // 用 actualTheme 而非 theme:auto+系统暗→moon, auto+系统亮→sun
    // V2.0 P3.6: 修复双入口不同步 BUG,集中到 applyTheme
    const themeToggle = document.getElementById('theme-toggle');
    if (themeToggle) {
      themeToggle.innerHTML = '<i data-lucide="' + (actualTheme === 'dark' ? 'moon' : 'sun') + '"></i>';
      window.safeCreateIcons();
    }
    // persistSettings 会写入外部设置文件 + localStorage + vault（见其实现）
    // 无谓写守卫：仅值变化时回写
    if (themeChanged) window.persistSettings();
  }

  /**
   * 切换皮肤（P0/P1/墨印 · 与明暗正交）
   * - 'p0'（默认）：Fluent 2 主实现
   * - 'p1'：shadcn/ui 皮肤（theme-override 覆写层，design-system/components/shadcn-ui/）
   * - 'moyin'：墨印皮肤（theme.css 覆写层，design-system/components/mo-yin/；朱砂印色 + 衬线标题）
   * 通过 <html data-skin="X"> 切换；CSS 用 :root[data-skin="X"] 块覆写令牌，图标走 iconDict 三集字典
   * V1 的 color 轴（custos 绿 / apple 蓝）已整体移除——Apple 蓝是演示残留，
   * 其位由 P1 皮肤取代（2026-09-26 用户拍板）；墨印为第三皮肤（2026-10-05 用户拍板）。
   * P4.1a.1: 从 dist/index.html L5646-5656 字节级搬入（原 applyColor）
   * 依赖 UI 块顶层 (全局): APP_SETTINGS (const) + UIState (state.js 顶层) + window.persistSettings
   */
  function applySkin(skin) {
    const normalized = (skin === 'p1' || skin === 'moyin') ? skin : 'p0';
    // 无谓写守卫：值未变且无 V1 color 键迁移残留时不回写
    const skinChanged = APP_SETTINGS.skin !== normalized || (UIState.appSettings.color !== undefined);
    APP_SETTINGS.skin = normalized;
    document.documentElement.setAttribute('data-skin', UIState.appSettings.skin);
    if (UIState.appSettings.color !== undefined) delete UIState.appSettings.color;  // V1 遗留 color 键迁移（随下次持久化清除）
    if (typeof window.reIconize === 'function') window.reIconize();  // 图标整包随皮肤重渲染（P1=shadcn / 墨印=Phosphor / P0=Fluent 2）
    // 无谓写优化：仅值变化（或有迁移清理）时回写
    if (skinChanged) window.persistSettings();
  }

  /**
   * 安全创建图标。
   *
   * ⚠️ 血泪教训：lucide 从 CDN 加载，偶发失败时 `lucide.createIcons()` 抛
   * ReferenceError → DOMContentLoaded 初始化中断 → 登录表单永远 disabled，
   * 用户被彻底锁死。因此**一切图标渲染都必须走本函数**，失败只损失图标、绝不中断业务。
   * P4.1a.1: 从 dist/index.html L5833-5844 字节级搬入
   */
  function safeCreateIcons() {
    try {
      if (window.lucide && typeof lucide.createIcons === 'function') lucide.createIcons();
    } catch (e) { /* 图标缺失不影响功能 */ }
  }

  // === P4.1a.1 暴露 (5 主题/DOM 工具) ===
  // 删 UI 块 L9143-L9147 段 5 个临时 window 暴露 (函数定义已搬走)
  window.safeCreateIcons = safeCreateIcons;
  window.applyDisplayName = applyDisplayName;
  window.applyWorkbenchName = applyWorkbenchName;
  window.applyTheme = applyTheme;
  window.applySkin = applySkin;

  // ============================================================
  // 渲染/剪贴板 (P4.1a.2a 从 UI 块搬入)
  // renderSettings (369 行大函数) 留给 P4.1a.2b 单独 1 步
  // ============================================================

  /**
   * P4.1a.2a: 5 函数从 dist/index.html UI 块字节级搬入 (仅缩进调整 4 → 2):
   * - renderRecords (84 行, UI 块 L7032)
   * - renderDashboard (12 行, UI 块 L6350)          ← P3.5 dashboard.js: 搬到 src/ui/dashboard.js
   * - startClock (20 行, UI 块 L6268)               ← P3.5 dashboard.js: 搬到 src/ui/dashboard.js
   * - clearClipboardIfNeeded (8 行, UI 块 L8903)   ← P3.5 dashboard.js: 搬到 src/ui/dashboard.js
   * - renderTodosFull (70 行, UI 块 L6542)          ← P3.5 dashboard.js: 搬到 src/ui/dashboard.js
   * 跨 IIFE 调用: UIState (state.js), $('#xxx') (dom.js $ 简写), $$ (dom.js $$),
   *               window.safeCreateIcons (本文件), window.renderCalendar / window.renderTodos /
   *               window.renderRecent / window.bindDashboardTodoDelegation / window.deleteTodo /
   *               window.toggleTodo (P3.5 dashboard.js 暴露),
   *               window.openDetail / window.openCopyWholeCard (P3.5 card-transfer.js 暴露),
   *               window.escapeHtml (P1.2.2 dom.js 暴露, 同 IIFE 函数同目录);
   * 同 IIFE 函数 (走词法作用域, 无需 window.): renderRecordCardHtml / emptyStateHtml / openCardMoreMenu
   */

  // P3.5 dashboard.js: renderDashboard 已搬到 src/ui/dashboard.js, 走 window.renderDashboard 调用

  function renderRecords() {
    // 更新 filter tab 计数
    $('#ft-count-all').textContent = UIState.cards.length;
    $('#ft-count-account').textContent = UIState.cards.filter(c => c.type === 'account').length;
    $('#ft-count-apikey').textContent = UIState.cards.filter(c => c.type === 'apikey').length;
    $('#ft-count-mt5').textContent = UIState.cards.filter(c => c.type === 'mt5').length;

    // R1（2026-09-27）：同步侧栏 nav-count（renderRecords 是全部增删卡路径唯一渲染入口，天然全路径同步）
    $('#nav-count-all').textContent = UIState.cards.length;
    $('#nav-count-account').textContent = UIState.cards.filter(c => c.type === 'account').length;
    $('#nav-count-apikey').textContent = UIState.cards.filter(c => c.type === 'apikey').length;
    $('#nav-count-mt5').textContent = UIState.cards.filter(c => c.type === 'mt5').length;

    const filter = UIState.state.recordsFilter;
    const search = UIState.state.recordsSearch.trim().toLowerCase();
    let cards = UIState.cards.slice();
    if (filter !== 'all') cards = cards.filter(c => c.type === filter);
    if (search) {
      cards = cards.filter(c =>
        (c.title || '').toLowerCase().includes(search) ||
        (c.note || '').toLowerCase().includes(search) ||
        (c.username || '').toLowerCase().includes(search) ||
        (c.service || '').toLowerCase().includes(search) ||
        (c.broker || '').toLowerCase().includes(search) ||
        (c.server || '').toLowerCase().includes(search)
      );
    }

    const content = $('#records-content');

    // 分组渲染
    const groups = [
      { type: 'account', dot: 'blue', title: '账号密码' },
      { type: 'apikey', dot: 'green', title: 'API KEY' },
      { type: 'mt5', dot: 'orange', title: 'MT5 账户' },
    ];

    if (filter !== 'all') {
      // 单分类视图: 不分组直接网格
      const group = groups.find(g => g.type === filter);
      $('#records-page-title').textContent = group.title;
      $('#records-page-subtitle').textContent = filter === 'account' ? '网站登录凭据' : filter === 'apikey' ? 'AI 模型凭证' : '经纪商交易账户';
      content.innerHTML = cards.length === 0
        ? emptyStateHtml()
        : '<div class="card-grid">' + cards.map(renderRecordCardHtml).join('') + '</div>';
    } else {
      // 全部: 分组展示
      $('#records-page-title').textContent = '信息记录';
      $('#records-page-subtitle').textContent = '统一管理三大类隐私敏感信息';
      const sections = groups.map(g => {
        const list = cards.filter(c => c.type === g.type);
        if (list.length === 0) return '';
        return '<div class="section-block">' +
          '<div class="section-block-head">' +
            '<span class="section-dot ' + g.dot + '"></span>' +
            '<h2 class="section-block-title">' + g.title + '</h2>' +
            '<span class="section-block-count">' + list.length + ' 条</span>' +
          '</div>' +
          '<div class="card-grid">' + list.map(renderRecordCardHtml).join('') + '</div>' +
        '</div>';
      }).join('');
      content.innerHTML = sections || emptyStateHtml();
    }

    // 绑定卡片点击
    $$('.record-card', content).forEach(el => {
      el.addEventListener('click', (e) => {
        if (e.target.closest('.icon-btn')) return;
        const id = el.dataset.id;
        window.openDetail(id);
      });
    });
    // 复制整卡按钮
    $$('[data-card-action="copy"]', content).forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = btn.closest('.record-card').dataset.id;
        // P3.5: openCopyWholeCard 已搬到 src/ui/card-transfer.js, 跨 IIFE 调走 window.
        window.openCopyWholeCard(id);
      });
    });
    // 更多按钮 - 弹出 Popover 菜单
    $$('[data-card-action="more"]', content).forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const id = btn.closest('.record-card').dataset.id;
        openCardMoreMenu(id, btn);
      });
    });
    window.safeCreateIcons();
  }

  // P3.5 dashboard.js: startClock 已搬到 src/ui/dashboard.js, 走 window.startClock 调用

  // P3.5 dashboard.js: clearClipboardIfNeeded 已搬到 src/ui/dashboard.js, 走 window.clearClipboardIfNeeded 调用


  // P3.5 dashboard.js: renderTodosFull 已搬到 src/ui/dashboard.js, 走 window.renderTodosFull 调用

  // === P4.1a.2a 暴露 (5 渲染/剪贴板函数) ===
