  // === P4.1b 暴露 (2 B 阶段函数) ===
  // 删 UI 块 L6511 maskPassword + L8935 copyToClipboard 段 2 个临时 window 暴露 (函数定义已搬走)
  // P4.1b-fix: 删 UI 块 L8976 fallbackCopy + L9006 onCopySuccess 段 2 个临时 window 暴露 (helper 已搬入同 IIFE, 内部互调走 scope chain)
  // P4 收尾 explore 审发现: startClipboardCountdown 在 UI 块 L5893/L8117/L8520 有 3 处裸调用 (IIFE 隔离作用域禁止 scope chain 跨 IIFE), 必须补 window. 暴露
  window.maskPassword = maskPassword;
  window.copyToClipboard = copyToClipboard;
