  window.generatePassword = generatePassword;
  window.openMql5Selector = openMql5Selector;
  window.persistCards = persistCards;
  window.timeAgo = timeAgo;
  window.formatDateCN = formatDateCN;
  window.typeLabel = typeLabel;

