  // === P3.5 BUG 修尾: 6 个 HTML onclick 依赖函数追加 (explore 审 BUG #1/#2/#3) ===

  async function toggleEdit() {
    // 写保护：云端不可写时拒绝进入编辑态（未保存的修改无法落云）
    if (!(await window.guardWrite('编辑卡片'))) return;
    UIState.state.editing = true;
    window.renderDetail();
  }
  function cancelEdit() {
    // V2.0 P3.6: 新建模式取消 = 删除临时卡 + 切回 records
    if (UIState.state.isNewCard) {
      const tempId = UIState.state.currentDetailId;
      if (tempId) {
        const idx = UIState.cards.findIndex(c => c.id === tempId);
        if (idx >= 0) UIState.cards.splice(idx, 1);
      }
      UIState.state.isNewCard = false;
      UIState.state.editing = false;
      UIState.state.currentDetailId = null;
      // 恢复 detail-back 按钮显示
      const backBtn = $('#detail-back');
      if (backBtn) backBtn.style.display = '';
      window.switchView('records');
      window.renderRecords();
      return;
    }
    UIState.state.editing = false;
    window.renderDetail();
  }
  /**
   * V2.0 P3.6.1: 把 detail 页编辑态 form 当前值回写到 card 对象
   * - 抽出来,saveEdit (新建/编辑都用) + renderDetail 重渲染前都用
   * - 防根因 1: saveEdit 新建模式早返回导致其他字段不回写
   * - 防根因 2: renderDetail container.innerHTML 重写时丢未保存输入
   * - 只改 card 对象, 不调 persistVault / renderDetail (调用方负责)
   */
  function writeFormToCard(card) {
    const container = $('#detail-content');
    if (!container) return;
    $$('.edit-input', container).forEach(inp => {
      const id = inp.id;
      if (id.startsWith('edit-title-')) card.title = inp.value;
      else if (id.startsWith('edit-url-')) card.url = inp.value;
      else if (id.startsWith('edit-username-')) card.username = inp.value;
      else if (id.startsWith('edit-password-')) card.password = inp.value;
      else if (id.startsWith('edit-service-')) card.service = inp.value;
      else if (id.startsWith('edit-broker-')) card.broker = inp.value;
      else if (id.startsWith('edit-accountType-')) card.accountType = inp.value;
      else if (id.startsWith('edit-login-')) card.login = inp.value;
      else if (id.startsWith('edit-investorPwd-')) card.investorPwd = inp.value;
      else if (id.startsWith('edit-tradePwd-')) card.tradePwd = inp.value;
      else if (id.startsWith('edit-server-')) card.server = inp.value;
      else if (id === 'edit-note-' + card.id) card.note = inp.value;
      // API KEY / 模型数组元素
      // ID 格式: edit-apikey-key-<cardId>-<itemId>
      // cardId 本身含连字符(如 apikey-001),必须按已知前缀+cardId 截取,不能 split('-')
      else if (id.startsWith('edit-apikey-key-')) {
        const keyId = id.slice(('edit-apikey-key-' + card.id + '-').length);
        const k = (card.apiKeys || []).find(x => x.id === keyId);
        if (k) k.key = inp.value;
      }
      else if (id.startsWith('edit-apikey-label-')) {
        const keyId = id.slice(('edit-apikey-label-' + card.id + '-').length);
        const k = (card.apiKeys || []).find(x => x.id === keyId);
        if (k) k.label = inp.value;
      }
      else if (id.startsWith('edit-model-name-')) {
        const modelId = id.slice(('edit-model-name-' + card.id + '-').length);
        const m = (card.models || []).find(x => x.id === modelId);
        if (m) m.name = inp.value;
      }
    });
    // BASE URL 多组聚合(id 格式: edit-baseurl-{url|label}-<cardId>-<itemId>)
    if (card.type === 'apikey') {
      const urlPrefix = 'edit-baseurl-url-' + card.id + '-';
      const labelPrefix = 'edit-baseurl-label-' + card.id + '-';
      // V2.0 P3.6.3: in-place 修改, 对齐 API KEY / MODEL 写法 (k.key = inp.value)
      // 之前 card.baseUrls = order.map(...) 整体赋值, addFieldRow 刚 push 但 input 未渲染的项被覆盖
      // 后果: 添加 BASE URL 按钮不起效 (BUG 2) + 编辑态 URL 一起消失 (BUG 3)
      (card.baseUrls || []).forEach(b => {
        if (b && b.id) {
          const urlInput = document.getElementById(urlPrefix + b.id);
          const labelInput = document.getElementById(labelPrefix + b.id);
          if (urlInput) b.url = urlInput.value;
          if (labelInput) b.label = labelInput.value;
        }
      });
      // V2.0 P3.6.2: 保留编辑态空行(对齐 HANDOFF §六 坑 #11 原则)
      // 之前 .filter(b => (b.url || '').trim()) 违反坑 #11 — "过滤逻辑只用于只读态/保存,编辑态必须保留空行"
      // 后果: addFieldRow push 立即被 writeFormToCard 过滤,用户看到"添加 BASE URL 按钮不起效"
      // getBaseUrls 已在只读态过滤(editing=false 时 arr.filter),不需要 writeFormToCard 再过滤
      // 向前兼容: 同步 baseUrl 字符串字段(取第一个 url, 老版本导入仍可读)
      // V2.0 P3.6.3: 仅在有 baseUrls 时更新, 避免清空老数据 card.baseUrl 字符串字段 (BUG 4)
      // 演示卡老数据: card.baseUrls=undefined, card.baseUrl='https://api.anthropic.com'
      // 之前: card.baseUrl = '' 清空字符串, getBaseUrls 返回 []
      // 现在: 保留 card.baseUrl 字符串, getBaseUrls 仍有 fallback
      if (card.baseUrls && card.baseUrls.length > 0) {
        card.baseUrl = card.baseUrls[0].url || '';
      }
      // 不动 card.baseUrl 字符串字段当 baseUrls 为空时(老数据兼容)
    }
  }
  async function saveEdit() {
    const card = UIState.cards.find(c => c.id === UIState.state.currentDetailId);
    if (!card) return;
    // V2.0 P3.6: 必填校验 — account/mt5 用 title, apikey 用 service (沿用 card-form.js service=title 约定)
    let titleVal;
    if (card.type === 'apikey') {
      const serviceInput = $('#edit-service-' + card.id);
      titleVal = serviceInput ? serviceInput.value.trim() : (card.service || card.title || '');
    } else {
      const titleInput = $('#edit-title-' + card.id);
      titleVal = titleInput ? titleInput.value.trim() : (card.title || '');
    }
    if (!titleVal) {
      window.showToast(card.type === 'apikey' ? '请填写服务名' : '请填写卡片标题', 'warning');
      return;
    }
    // V2.0 P3.6.1: 修复根因 1 — 不管新建/编辑,都先跑 form 回写到 card
    writeFormToCard(card);
    // ── 写闸门：await 保存结果，成功才收尾；失败保留编辑态（内容不丢、可重试）──
    const saveBtn = $('#btn-save');
    if (saveBtn) saveBtn.disabled = true;              // 防连点（慢网络）
    // V2.0 P3.6: 新建模式特殊处理 — 补 avatarColor + persistVault + 切回 records
    if (UIState.state.isNewCard) {
      // V2.0 P3.6.3: 修正 P3.6.2 R1 修复方向(删 R1 是对的, 但漏了同步写 card.title)
      // apikey 模式没 edit-title- input, writeFormToCard 不写 card.title
      // → records 列表/详情页用 card.title 渲染 → 空字符串 → 标题空白 (BUG 1)
      // 修复: 显式写 card.title = card.service (apikey 走 service) || titleVal (其他)
      if (card.type === 'apikey') {
        card.title = card.service || titleVal;
      } else {
        card.title = titleVal;
      }
      card.avatarColor = window.pickAvatarColor(card.title);
      card.updatedAt = Date.now();
      // V2.0 P3.6.5: 先清 isNewCard 再 persist(explore 数据安全审查问题 2 配套)
      // persistVault 现在会过滤 isNewCard 草稿卡 — 若先 persist 后清标志, 新卡会被过滤掉不保存!
      UIState.state.isNewCard = false;
      const okNew = await window.persistVault();
      if (saveBtn) saveBtn.disabled = false;
      if (!okNew) {
        // 保存失败：恢复草稿标志、保留编辑态（草稿仍在内存，用户可重试；失败文案由 persistVault 弹）
        UIState.state.isNewCard = true;
        return;
      }
      UIState.state.editing = false;
      UIState.state.currentDetailId = null;
      window.showToast('已添加「' + card.title + '」', 'success');
      window.renderDashboard();
      window.switchView('records');
      window.renderRecords();
      return;
    }
    card.updatedAt = Date.now();
    const okEdit = await window.persistVault();
    if (saveBtn) saveBtn.disabled = false;
    if (!okEdit) return;                               // 保存失败：保留编辑态，内容不丢
    UIState.state.editing = false;
    window.showToast('已保存', 'success');
    window.renderDetail();
  }

  async function confirmDeleteCard(id) {
    const card = UIState.cards.find(c => c.id === id);
    if (!card) return;
    // 写保护：云端不可写时拒绝进入删除流程
    if (!(await window.guardWrite('删除卡片'))) return;
    window.openModal(
      '<div class="modal confirm-dialog">' +
        '<div class="modal-body">' +
          '<div class="confirm-icon"><i data-lucide="alert-triangle"></i></div>' +
          '<h3 class="confirm-title">确认删除「' + escapeHtml(card.title) + '」？</h3>' +
          '<p class="confirm-desc">此操作不可撤销。删除后该卡片的所有字段将永久消失。</p>' +
        '</div>' +
        '<div class="modal-footer">' +
          '<button class="btn btn-ghost" data-custos-action="closeModal()">取消</button>' +
          '<button class="btn btn-danger" data-custos-action="doDeleteCard(\'' + encodeURIComponent(id).replace(/'/g, '%27') + '\')">确认删除</button>' +
        '</div>' +
      '</div>'
    );
  }
  async function doDeleteCard(id) {
    const idx = UIState.cards.findIndex(c => c.id === id);
    if (idx >= 0) {
      const [card] = UIState.cards.splice(idx, 1);
      const ok = await window.persistVault();
      if (!ok) {
        // 保存失败：还原内存（没保存成功的删除不算已删除）；失败文案由 persistVault 弹
        UIState.cards.splice(idx, 0, card);
        return;
      }
      window.closeModal();
      window.showToast('已删除', 'success');
      window.switchView('records');
      window.renderRecords();
    }
  }

  // P3.5: buildCardCopyText 已搬到 src/ui/card-transfer.js, 走 window.buildCardCopyText 调用
  // P3.5: buildCardEncryptedText 已搬到 src/ui/card-transfer.js, 走 window.buildCardEncryptedText 调用
